-- ============================================================
-- 1. CREATE TABLE
-- ============================================================
create table if not exists tours (
  id            integer primary key,
  name          text not null,
  image         text,
  location      text,
  duration      text,
  activity      text,
  difficulty    text,
  price         numeric,
  price_label   text,
  category      text,
  tag           text,
  tag_color     text,
  color         text,
  description    text,
  highlights    text[],
  included      text[],
  not_included  text[],
  long_desc     text
);

-- Enable public read access (no login required)
alter table tours enable row level security;
create policy "Public read" on tours for select using (true);

-- ============================================================
-- 2. INSERT ALL 34 TOURS
-- ============================================================
on conflict (id) do nothing;
